<?php

declare(strict_types=1);

namespace App\Features\Blog\Infra\Requests;

use App\Features\Shared\Infra\Services\ActiveLocaleService;
use Illuminate\Foundation\Http\FormRequest;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Str;

/**
 * `POST /admin/tags` / `PUT /admin/tags/{tag}`: the shared slug
 * (kebab-case regex, max 100, unique across `article_tags` with the
 * current tag ignored on update — except the auto-generated value,
 * resolved server-side) and the per-locale `name` (required per ACTIVE
 * locale, max 100). The tag↔skill name cross-check does NOT run here —
 * it is the store/update use cases' repository probe, surfacing a
 * `name` validation error.
 */
final class StoreTagRequest extends FormRequest
{
    public function __construct(
        private readonly ActiveLocaleService $locales,
    ) {
        parent::__construct();
    }

    /** @return array<string, mixed> */
    public function rules(): array
    {
        $rules = [
            'slug' => [
                'required',
                'string',
                'regex:/^[a-z0-9]+(?:-[a-z0-9]+)*$/',
                'max:100',
                function (string $attribute, mixed $value, callable $fail): void {
                    if ($this->isAutoGeneratedSlug((string) $value)) {
                        return;
                    }

                    $exists = DB::table('article_tags')
                        ->where('slug', $value)
                        ->when(
                            $this->route('tag') !== null,
                            fn ($query): mixed => $query->where('id', '!=', $this->route('tag')),
                        )
                        ->exists();

                    if ($exists) {
                        $fail(__('validation.unique', [
                            'attribute' => $this->attributes()['slug'] ?? 'slug',
                        ]));
                    }
                },
            ],
        ];

        foreach ($this->activeLocales() as $locale) {
            $rules["name.$locale"] = ['required', 'string', 'max:100'];
        }

        return $rules;
    }

    /**
     * @return array<string, string>
     */
    public function attributes(): array
    {
        $attributes = ['slug' => __('admin.tags.slug')];
        foreach ($this->activeLocales() as $locale) {
            $attributes["name.$locale"] = __('admin.tags.name').' ['.strtoupper($locale).']';
        }

        return $attributes;
    }

    /**
     * The submitted slug is "auto-generated" when it equals the naive
     * generation of the EN name or the currently stored slug on update —
     * such values skip the uniqueness rejection (the use case
     * re-resolves them with a collision suffix).
     */
    private function isAutoGeneratedSlug(string $value): bool
    {
        $enName = $this->input('name.en');

        if (is_string($enName) && $value === Str::slug($enName)) {
            return true;
        }

        $tagId = $this->route('tag');
        if ($tagId === null) {
            return false;
        }

        return $value === DB::table('article_tags')->where('id', $tagId)->value('slug');
    }

    /**
     * @return string[]
     */
    private function activeLocales(): array
    {
        return $this->locales->activeLocales();
    }
}
